// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address to, uint256 id, address from, bytes memory data) public {
        vm.assume(to != address(0));
        vm.assume(from != address(0));
        vm.assume(to != address(c));

        bytes4 result;
        try c.onERC721Received(address(0), from, id, data) returns (bytes4 ret) {
            result = ret;
        } catch {
            result = bytes4(0);
        }

        assertTrue(result == 0x150b7a02);
    }
}
